function economy4(m,side,dt){let s=m.sides[side],plan=m.plans[side],other=m.sides[1-side];for(let p of s.heroes){if(p.deadUntil>m.clock)continue;let meta=heroMeta4(p.hero),base=[560,520,450,280,255][p.role],lane=1;if(m.clock<600){let opposite=other.heroes[p.role===0?2:p.role===2?0:p.role],matchup=(meta.lane-heroMeta4(opposite.hero).lane)*.035;lane=clamp(.91+(p.skill-84)*.004+matchup,.7,1.15)}let access=.81+s.control*.32,focus=plan==='farm'?(p.role===0?1.17:p.role<=2?1.04:.94):plan==='split'?1.08:plan==='rosh'?.82:plan==='siege'||plan==='throne'?.80:1;let income=base*lane*access*focus*(.94+p.mastery*.06)*(1+(meta.farm-3)*.018)*(dt/60);income*=.96+rng()*.08;p.nw+=income;p.bank+=income;p.xp+=income*(p.role<3?1.1:1.5);p.level=Math.min(30,1+Math.floor(Math.sqrt(p.xp/42)));p.health=clamp(p.health+dt*.24,0,100);let reserve=m.clock>=1800&&p.role<3?buybackCost4(p):0;if(p.bank>=p.nextItem+reserve){p.bank-=p.nextItem;p.items.push({at:m.clock,cost:p.nextItem,name:p.items.length===0?'Мобильность':p.items.length===1?'Основной предмет':p.items.length===2?'Защитный тайминг':'Усиление'});event4(m,p.name+' завершает '+p.items.at(-1).name.toLowerCase()+': '+cash(p.nextItem)+'.','item',{side});p.nextItem=Math.min(6000,Math.round(p.nextItem*1.37));}}}
