function fightingPower4(m,side,context='field'){let s=m.sides[side],stage=m.clock<720?'early':m.clock<2100?'mid':'late',power=alive4(m,side).reduce((n,p)=>{let h=heroMeta4(p.hero),roleWeight=[1.2,1.15,1.1,.78,.74][p.role],stats=55+Math.sqrt(Math.min(p.nw,65000))*1.25+p.level*6;let comfort=.79+p.mastery*.21,skill=.78+p.skill/350,ready=p.ultUntil<=m.clock?1+(h.control-2)*.045:.88;return n+stats*roleWeight*comfort*skill*(.8+h[stage]*.075)*(.7+p.health*.003)*ready*(.9+(p.form||80)*.001)*(.92+(p.morale||80)*.0008)*(.85+(p.energy??85)*.0015)},0);if(context==='highground-defense')power*=1.23+avg(s.heroes.map(p=>heroMeta4(p.hero).wave))*.018;if(s.aegisUntil>m.clock)power*=1.07;power*=.93+s.vision*.14;if(s.team===S.club)power*=.94+S.chem*.0004+S.coach*.0004;return power}
