function choosePlan4(m,side){let s=m.sides[side],enemy=m.sides[1-side],order=m.orders[side];if(order.until>m.clock&&order.type!=='coach')return order.type;let nw=net4(s)-net4(enemy),living=alive4(m,side).length,enemyLiving=alive4(m,1-side).length;if(living<3||nw<-9000&&enemyLiving>=4)return 'defend';if(m.clock<420)return 'farm';if(enemyLiving<=2&&living>=3)return enemy.lanes.some(l=>l.towers[2].hp<=0)?'throne':'siege';if(m.clock>1000&&m.roshan.alive&&nw>2000&&living>=4&&towerCount4(enemy)>=1)return 'rosh';if(m.clock>600&&(nw>1800||s.aegisUntil>m.clock))return 'siege';if(m.clock>540&&avg(s.heroes.map(p=>heroMeta4(p.hero).push))>=3.5&&nw>-1500)return 'siege';if(nw<-3000)return 'split';return m.clock<1200?'farm':'vision'}
