function availableTarget4(m,side){let defender=m.sides[1-side],i=targetLane4(m,side),lane=defender.lanes[i],tower=lane.towers.find(t=>t.hp>0);if(tower)return {entity:tower,label:'T'+tower.tier+' · '+['верх','мид','низ'][i],lane:i,tier:tower.tier,type:'tower'};if(lane.rax.hp>0&&m.plans[side]!=='throne')return {entity:lane.rax,label:'казармы · '+['верх','мид','низ'][i],lane:i,tier:3,type:'rax'};let t4=defender.t4.find(t=>t.hp>0);if(t4)return {entity:t4,label:'T4',lane:i,tier:4,type:'tower'};return {entity:defender.ancient,label:'Древний',lane:i,tier:5,type:'ancient'}}
