function fight4(m,attacker=null,highground=false){if(alive4(m,0).length<2||alive4(m,1).length<2)return;let powers=[0,1].map(side=>fightingPower4(m,side,highground&&side!==attacker?'highground-defense':'field'));let econ=Math.log(Math.max(1,net4(m.sides[0]))/Math.max(1,net4(m.sides[1]))),edge=Math.log(Math.max(1,powers[0])/Math.max(1,powers[1]))*7+econ*2.6+m.smokeBonus[0]-m.smokeBonus[1];let chance=1/(1+Math.exp(-edge)),winner=rng()<chance?0:1,loser=1-winner;let big=m.clock>900&&rng()<.60,targets=alive4(m,loser).slice().sort((a,b)=>rng()-.5),count=Math.min(targets.length,big?int(2,5):int(1,2));event4(m,(highground?'Бой у возвышенности':'Столкновение на карте')+': '+S.teams[m.sides[winner].team].short+' выигрывает размен.','fight',{winner,highground});for(let p of targets.slice(0,count))kill4(m,winner,p);let retaliation=big?int(0,2):int(0,1);for(let p of alive4(m,winner).slice().sort((a,b)=>rng()-.5).slice(0,retaliation))kill4(m,loser,p);for(let side of [0,1])for(let p of alive4(m,side)){p.health=clamp(p.health-int(8,30),20,100);if(big&&p.ultUntil<=m.clock&&heroMeta4(p.hero).control>=4)p.ultUntil=m.clock+heroMeta4(p.hero).ult}m.smokeBonus=[0,0];m.lastFight=m.clock;m.nextFight=m.clock+int(90,185)}
function objectives4(m,side,dt){let s=m.sides[side],enemy=m.sides[1-side],plan=m.plans[side],living=alive4(m,side),opponents=alive4(m,1-side);if(plan==='rosh'&&m.clock>=480&&m.roshan.alive&&living.length>=3){let contested=m.plans[1-side]==='rosh'&&opponents.length>=3;if(contested&&m.clock-m.lastFight>70){fight4(m);return}let safe=opponents.length<3||fightingPower4(m,side)>fightingPower4(m,1-side)*.95||m.plans[1-side]==='farm';if(safe){m.roshan.progress[side]+=dt*(.55+living.length*.15);if(m.roshan.progress[side]>=100){m.roshan.alive=false;m.roshan.spawnAt=m.clock+int(480,660);m.roshan.progress=[0,0];s.roshKills++;s.aegisUntil=m.clock+300;s.aegisHero=s.heroes.reduce((best,p,i,arr)=>p.role===0?i:best,0);for(let p of living)addGold4(p,180);event4(m,S.teams[s.team].short+' забирает Рошана. Аегис у '+s.heroes[s.aegisHero].name+' на 5 минут.','roshan',{side});if(side===0&&m.orders[0].type==='rosh')m.orders[0]={type:'coach',until:0}}}return}
if(!['siege','split','throne'].includes(plan)||living.length<(plan==='split'?1:3)||m.clock<300)return;let target=availableTarget4(m,side),wave=(side===0?1:-1)*m.waves[target.lane];if(wave<14)return;if(target.tier>=3&&opponents.length>=3&&m.clock-m.lastFight>80&&enemy.glyphUntil<=m.clock){fight4(m,side,true);if(alive4(m,side).length<3)return}let defense=opponents.length>=3?(target.tier>=3?.16:.42):opponents.length===2?.62:1;let siege=avg(living.map(p=>heroMeta4(p.hero).push)),goldStrength=Math.sqrt(net4(s)/Math.max(8000,net4(enemy)));let damage=(14+living.length*4+siege*5)*dt/.65*defense*clamp(goldStrength,.65,1.7);if(plan==='split')damage*=.44;if(s.aegisUntil>m.clock)damage*=1.18;if(enemy.glyphUntil>m.clock)damage=0;else if(target.tier>=3&&side===0&&enemy.glyphReady<=m.clock&&target.entity.hp<target.entity.max*.5){enemy.glyphUntil=m.clock+10;enemy.glyphReady=m.clock+420;event4(m,S.teams[enemy.team].short+' использует укрепление строений.','glyph',{side:1-side});damage=0}target.entity.hp=Math.max(0,target.entity.hp-damage);if(target.entity.hp===0){event4(m,S.teams[s.team].short+' разрушает '+target.label+'.','objective',{side,target:target.type});if(target.type!=='ancient'){for(let p of s.heroes)addGold4(p,target.type==='tower'?160:130)}else{m.finishedSide=side;return}}}
function simulateTick4(m,dt=10){if(m.finishedSide!=null)return;m.clock+=dt;for(let side of [0,1]){let s=m.sides[side];if(s.nextSmoke<=m.clock){s.smokes=Math.min(3,s.smokes+1);s.nextSmoke=m.clock+480}if(s.aegisUntil&&s.aegisUntil<=m.clock){s.aegisUntil=0;event4(m,S.teams[s.team].short+': время Аегиса истекло.','aegis',{side})}m.plans[side]=choosePlan4(m,side)}
if(!m.roshan.alive&&m.roshan.spawnAt<=m.clock){m.roshan.alive=true;event4(m,'Рошан снова появился.','roshan')}
let power=net4(m.sides[0])-net4(m.sides[1]),ratio=power/Math.max(20000,(net4(m.sides[0])+net4(m.sides[1]))/2);for(let side of [0,1]){let s=m.sides[side],sign=side===0?1:-1,desired=clamp(.5+sign*ratio*.5+(alive4(m,side).length-alive4(m,1-side).length)*.05+(m.plans[side]==='vision'?.08:0),.12,.88);s.control+=(desired-s.control)*.04;s.vision=clamp(s.vision+(m.plans[side]==='vision'?.005:-.001),.2,.85);economy4(m,side,dt)}
for(let i=0;i<3;i++){let influence=(m.sides[0].control-m.sides[1].control)*2+(m.plans[0]==='split'?.45:0)-(m.plans[1]==='split'?.45:0);m.waves[i]=clamp(m.waves[i]+influence*dt*.16+int(-3,3),-100,100)}
if(m.clock>=m.nextFight){let quiet=m.plans.includes('farm')&&m.clock<600;if(quiet&&rng()<.45)m.nextFight=m.clock+80;else fight4(m)}
for(let side of (rng()<.5?[0,1]:[1,0])){objectives4(m,side,dt);if(m.finishedSide!=null)break}sync4(m);if(m.clock%60===0)snapshot4(m)}
function playMap(){let a=S.active;if(!a||a.seriesDone||a.live)return;pauseLive4(false);a.live=makeLive4(a,autoDraft());go('match')}
function advanceMap(choice=null){let m=S.active?.live;if(!m||m.engine!==4)return;if(choice)issueOrder4(choice,false);pauseLive4(false);let target=(Math.floor(m.clock/600)+1)*600;while(m.clock<target&&m.finishedSide==null)simulateTick4(m,10);if(m.finishedSide!=null)finishMap();else{event4(m,'Пауза штаба. Выбери план на следующий отрезок.','pause');render()}}
function issueOrder4(type,redraw=true){let m=S.active?.live;if(!m||!ORDERS4[type]||m.finishedSide!=null)return false;if(m.clock-m.commandAt<20&&type!=='coach'){if(redraw)toast('Следующую команду можно отдать через '+Math.ceil(20-m.clock+m.commandAt)+' игровых секунд.');return false}if(type==='smoke'){if(!m.sides[0].smokes){if(redraw)toast('Нет зарядов смоука.');return false}m.sides[0].smokes--;m.smokeBonus[0]=.65;m.nextFight=Math.min(m.nextFight,m.clock+30);m.orders[0]={type:'vision',until:m.clock+120}}else if(type==='rosh'&&!m.roshan.alive){if(redraw)toast('Рошан ещё не появился.');return false}else m.orders[0]={type,until:type==='coach'?0:m.clock+180};m.commandAt=m.clock;m.decisions.push({minute:Math.floor(m.clock/60),sec:m.clock,key:type,title:ORDERS4[type][0]});event4(m,'Приказ менеджера: '+ORDERS4[type][0]+'.','order',{side:0});if(redraw)render();return true}
function chooseDecision(type,minute){let m=S.active?.live;if(!m||Math.floor(m.clock/60)!==minute)return;if(issueOrder4(type,false))advanceMap()}
function decisionView(m){return `<section class="panel decision-panel"><div class="eyebrow">ШТАБ · ${clock4(m.clock)}</div><h2 style="margin-top:10px">${stage4(m)} · выбери план</h2><p>Перевес ${m.gold>=0?'+':'−'}${cash(Math.abs(m.gold))}. В строю ${alive4(m,0).length} против ${alive4(m,1).length}. ${m.sides[0].aegisUntil>m.clock?'Аегис позволяет безопаснее штурмовать.':'Перед штурмом оцени Аегис, ультимейты и выкупы.'}</p><div class="command-grid">${Object.entries(ORDERS4).map(([type,v])=>`<button onclick="chooseDecision('${type}',${Math.floor(m.clock/60)})"><b>${v[0]}</b><small>${v[1]}</small></button>`).join('')}</div><div class="actions" style="margin-top:14px">${btn('Продолжить текущий план · +10 мин','advanceMap()',true)}</div></section>`}
function finishMap(){let a=S.active,m=a?.live;if(!m||m.finishedSide==null)return;pauseLive4(false);let win=m.finishedSide===0;sync4(m);snapshot4(m);event4(m,(m.resultReason==='gg'?'Карта завершена сдачей. Победа ':'Древний разрушен. Победа ')+(win?my().name:S.teams[a.opponent].name)+'.','end');let result={...m,win,duration:Math.round(m.clock/60),durationSec:m.clock,prob:m.initialChance,finalChance:positionScore4(m),mode:m.mode};delete result.sides;result.players=m.players.map(p=>({...p}));result.enemyPlayers=m.enemyPlayers.map(p=>({...p}));a.maps.push(result);a.score[win?0:1]++;a.live=null;roster().forEach(p=>{p.fatigue=clamp(p.fatigue+fatigueDelta21(p,int(5,9)));p.morale=clamp(p.morale+(win?3:-3));p.form=clamp(p.form+(win?1:-1))});let need=isFinal(a)?3:2;a.seriesDone=a.score.some(n=>n>=need);if(a.seriesDone){let seriesWin=a.score[0]>=need;S[seriesWin?'wins':'losses']++;S.history.unshift({day:S.day,event:nextEvent().name,stage:a.phase==='groups'?'Групповой этап':roundTitle(a.round,a.totalRounds||3),opponent:S.teams[a.opponent].name,score:[...a.score],win:seriesWin,maps:structuredClone(a.maps)});log((seriesWin?'Победа':'Поражение')+' против '+S.teams[a.opponent].name+' — '+a.score.join(':'))}render()}
function clock4(sec){return Math.floor(sec/60)+':'+String(Math.floor(sec%60)).padStart(2,'0')}
function setMatchMode4(mode){let m=S.active?.live;if(!['step','live'].includes(mode))return;pauseLive4(false);S.matchMode=mode;if(m)m.mode=mode;render()}
function setSpeed4(speed){if(![5,10,30].includes(speed))return;S.liveSpeed=speed;if(S.active?.live)S.active.live.speed=speed;render()}
function pauseLive4(redraw=true){if(liveTimer4!==null){clearInterval(liveTimer4);liveTimer4=null}liveRunning4=false;if(redraw&&page==='match')render()}
function toggleLive4(){let m=S.active?.live;if(!m||m.mode!=='live')return;if(liveRunning4){pauseLive4();return}liveRunning4=true;let fraction=0;liveTimer4=setInterval(()=>{if(page!=='match'||document.hidden||!S.active?.live){pauseLive4(false);return}let map=S.active.live;fraction+=map.speed;while(fraction>=10&&map.finishedSide==null){simulateTick4(map,10);fraction-=10}if(map.finishedSide!=null){finishMap();return}render()},1000);render()}
function glyph4(){let m=S.active?.live;if(!m||m.sides[0].glyphReady>m.clock)return;let s=m.sides[0];s.glyphUntil=m.clock+10;s.glyphReady=m.clock+420;event4(m,'Менеджер использует укрепление: строения временно не получают урон.','glyph',{side:0});render()}
function buyback4(i){let m=S.active?.live,p=m?.sides[0].heroes[i];if(!p||p.deadUntil<=m.clock)return;let cost=buybackCost4(p);if(p.buybackUntil>m.clock||p.bank<cost){toast('Для выкупа нужен доступный кулдаун и '+cash(cost)+' в банке героя.');return}addGold4(p,-cost);p.deadUntil=m.clock;p.buybackUntil=m.clock+480;event4(m,p.name+' использует выкуп за '+cash(cost)+'.','buyback',{side:0});render()}
function setTactic(k){if(S.active?.live){toast('На карте используй приказы штаба.');return}if(TACTICS[k]){S.tactic=k;render()}}
function goldChart4(m){let points=m.snapshots||[];if(points.length<2)return '<p class="sub">График появится после первой игровой минуты.</p>';let last=Math.max(600,m.clock||m.durationSec||points.at(-1).sec),range=Math.max(5000,...points.map(p=>Math.abs(p.gold))),path=points.map((p,i)=>(i?'L':'M')+(20+p.sec/last*660).toFixed(1)+' '+(90-p.gold/range*66).toFixed(1)).join(' ');return `<svg viewBox="0 0 700 180" class="gold-chart" role="img" aria-label="История перевеса золота"><line x1="20" x2="680" y1="90" y2="90" stroke="#35424c"/><path d="${path}" fill="none" stroke="#b9ef73" stroke-width="2.5"/><text x="20" y="18">+${cash(range)}</text><text x="20" y="174">−${cash(range)}</text><text x="620" y="174">${clock4(last)}</text></svg>`}
function heroTable4(m,side){let ps=m.sides?m.sides[side].heroes:side===0?m.players:m.enemyPlayers;if(!ps)return '';let now=m.clock??m.durationSec??m.duration*60,team=S.teams[side===0?S.club:S.active.opponent];return `<section class="panel"><div class="section-head"><h2>${esc(team.name)}</h2><span class="tag dim">${m.sides?cash(net4(m.sides[side])):'Итоги карты'}</span></div><div class="table-wrap"><table><thead><tr><th>ИГРОК / ГЕРОЙ</th><th>K / D / A</th><th>LVL</th><th>NET</th><th>СТАТУС</th></tr></thead><tbody>${ps.map((p,i)=>`<tr class="${p.deadUntil>now?'dead-hero':''}"><td><b>${esc(p.name)}</b><span class="sub">${esc(p.hero)} · ${p.observed?'из пула':'ролевой резерв'}</span></td><td>${p.k}/${p.d}/${p.a}</td><td>${p.level||'–'}</td><td>${p.nw?cash(p.nw):'–'}<span class="sub">Банк ${cash(p.bank||0)}</span></td><td>${p.deadUntil>now?`<span class="red">${Math.ceil(p.deadUntil-now)} с.</span>${side===0&&m.sides?`<button class="buyback-btn" onclick="buyback4(${i})" ${p.buybackUntil>now||p.bank<buybackCost4(p)?'disabled':''}>Выкуп ${cash(buybackCost4(p))}</button>`:''}`:`<span class="green">В игре</span><span class="sub">${p.ultUntil>now?'Ульт '+Math.ceil(p.ultUntil-now)+' с.':'Ульт готов'}</span>`}</td></tr>`).join('')}</tbody></table></div></section>`}
function objectivesView4(m){return `<section class="panel"><div class="section-head"><h2>Постройки и объекты</h2><span class="tag dim">Структура базы</span></div><div class="lane-board">${[0,1].map(side=>{let s=m.sides[side];return `<div><h3>${esc(S.teams[s.team].short)} · защита</h3>${s.lanes.map((l,i)=>`<div class="lane-row"><span>${['Верх','Мид','Низ'][i]}</span>${l.towers.map(t=>`<span class="tower ${t.hp<=0?'destroyed':''}" title="T${t.tier}: ${Math.round(t.hp)}/${t.max}">T${t.tier}<i style="width:${t.hp/t.max*100}%"></i></span>`).join('')}<span class="tower ${l.rax.hp<=0?'destroyed':''}">RAX<i style="width:${l.rax.hp/l.rax.max*100}%"></i></span></div>`).join('')}<div class="ancient-bar"><span>Древний ${Math.round(s.ancient.hp)}/${s.ancient.max}</span><div class="bar"><b style="width:${s.ancient.hp/s.ancient.max*100}%"></b></div></div><p class="sub">T4: ${s.t4.map(t=>Math.round(t.hp/t.max*100)+'%').join(' / ')} · Аегис: ${s.aegisUntil>m.clock?clock4(s.aegisUntil-m.clock):'нет'} · Смоуки: ${s.smokes}</p></div>`}).join('')}</div><div class="notice">Рошан: ${m.roshan.alive?'жив':`новое появление через ${clock4(m.roshan.spawnAt-m.clock)}`} · Укрепление: ${m.sides[0].glyphReady>m.clock?clock4(m.sides[0].glyphReady-m.clock):'готово'}. Сначала нужно открыть линию и разрушить T4, затем — Древнего.</div></section>`}
function liveControls4(m){return `<section class="panel command-panel"><div class="section-head"><h2>Приказы на ходу</h2><span class="tag">${liveRunning4?'● Часы идут':'Ⅱ Пауза'}</span></div><p>Сейчас: <b class="green">${ORDERS4[m.plans[0]]?.[0]||m.plans[0]}</b>. Приказ действует 3 игровые минуты, затем команда возвращается к решениям тренера.</p><div class="command-grid">${Object.entries(ORDERS4).map(([type,v])=>`<button class="${m.orders[0].type===type&&m.orders[0].until>m.clock?'selected':''}" onclick="issueOrder4('${type}')"><b>${v[0]}</b><small>${v[1]}</small></button>`).join('')}</div><div class="save-actions" style="margin-top:14px">${btn('Укрепление','glyph4()',false,m.sides[0].glyphReady>m.clock)}${btn('Сохранить на паузе',"go('saves')")}</div></section>`}
function matchView(){let a=S.active;if(!a)return home();let live=!!a.live,m=a.live||a.maps.at(-1),opp=S.teams[a.opponent],stage=a.phase==='groups'?'Группа '+a.groups.find(g=>g.teams.includes(S.club)).name+' · тур '+(a.groupDay+1)+'/3':roundTitle(a.round,a.totalRounds||3),time=m?(m.clock??m.durationSec??m.duration*60):0,mode=live?m.mode:(S.matchMode||m?.mode||'step');let header=head('TACTICAL MATCH ENGINE / 5',nextEvent().name,stage,`<span class="tag">${isFinal(a)?'BO5':'BO3'} · ${mode==='live'?'LIVE':'ПОШАГОВЫЙ'}</span>`);let control=`<div class="mode-strip"><div class="mode-switch"><button class="${mode==='step'?'primary':''}" onclick="setMatchMode4('step')">Паузы 10 минут</button><button class="${mode==='live'?'primary':''}" onclick="setMatchMode4('live')">Лайв · часы идут</button></div><span class="sub">${mode==='live'?'Приказы можно отдавать, пока идёт игра.':'На паузе выбери план и сыграй следующий отрезок.'}</span></div>`;let main=`<section class="panel hero tactical-hero"><div class="matchup">${teamDisplay(my())}<div class="live-centre"><span class="eyebrow">СЕРИЯ ${a.score.join(' : ')}</span><strong>${live?clock4(time):a.seriesDone?'СЕРИЯ':m?'GG':'ДРАФТ'}</strong><span>${live?stage4(m):a.seriesDone?'завершена':'Карта '+(a.maps.length+(live||!m?1:0))}</span></div>${teamDisplay(opp)}</div><div class="hero-foot"><span>${live?'Состояние карты меняется каждые 10 игровых секунд.':'Драфт из индивидуальных пулов и задач команды.'}</span><div class="save-actions">${btn('Турнир',"showBracket(S.active.event)")}${a.seriesDone?btn('Подвести итог серии →','finishSeries()',true):!live?btn('Автодрафт карты '+(a.maps.length+1)+' →','playMap()',true):mode==='live'?btn(liveRunning4?'Ⅱ Пауза':'▶ Запустить часы','toggleLive4()',true):''}</div></div></section>`;
let content=header+control+main;if(!m)return content+'<div class="notice">Новая карта начинается с автоматического драфта. В пошаговом режиме игра остановится каждые 10 минут; в лайв-режиме часы идут непрерывно, а приказы меняют поведение команды на ходу. Камбэки требуют боёв и взятия объектов; случайного выбора победителя в конце нет.</div>';content+=`<div class="live-stats">${stat('Убийства',m.kills+' : '+m.deaths,'Победа определяется разрушением Древнего')}${stat('Перевес золота',(m.gold>=0?'+':'−')+cash(Math.abs(m.gold)),live?'Отношение экономик: '+(net4(m.sides[0])/Math.max(1,net4(m.sides[1]))).toFixed(2)+'×':'Итоговый перевес')}${stat('В игре',live?alive4(m,0).length+' : '+alive4(m,1).length:'Карта окончена','Смерти и возрождения считаются отдельно')}${stat('Объекты',(m.towers||[0,0]).join(' : '),'Снесённые башни · Рошан '+(m.rosh||[0,0]).join(':'))}</div>`;
if(live&&mode==='live')content+=`<div class="live-speed"><span class="sub">Скорость · 1 реальная секунда</span>${[5,10,30].map(v=>btn(v+' игровых сек.',`setSpeed4(${v})`,m.speed===v)).join('')}<span class="sub">Выход из матч-центра или скрытие вкладки ставит часы на паузу.</span></div>`+liveControls4(m);else if(live)content+=decisionView(m);
content+=`<div class="columns"><section class="panel"><div class="section-head"><h2>Экономика карты</h2><span class="tag dim">История событий</span></div>${goldChart4(m)}</section><section class="panel feed-panel"><h2>Лента матча</h2><div class="live-feed" aria-live="polite">${m.events.slice(-12).reverse().map(e=>`<div class="feed-event ${e.type||''}"><small>${clock4(e.sec??e.t*60)}</small><span>${esc(e.text)}</span></div>`).join('')}</div></section></div>`;if(live)content+=objectivesView4(m);content+=`<div class="roster-grid">${heroTable4(m,0)}${heroTable4(m,1)}</div><section class="panel" style="margin-top:20px"><h2>Драфт текущей карты</h2><p class="sub">Баны: ${(m.draft?.bans||[]).map(esc).join(' · ')}</p><div class="draft-notes">${m.draft?.details?.flat().map(p=>`<span class="draft-note ${p.observed?'':'reserve'}"><b>${esc(p.player)}</b> · ${esc(p.hero)}<small>${p.observed?p.games+' матчей в срезе профиля':'Ролевой резерв: нет подтверждённой частоты в срезе'}</small></span>`).join('')||'<p class="sub">Для старой карты статистика драфта не пересчитывается.</p>'}</div></section>`;return content}
function heroPoolsView4(){let ps=S.players.filter(p=>!p.fiction);return head('SCOUTING DATABASE','Индивидуальные пулы героев','Исторический срез esports-профилей. Не заявляется как статистика текущего патча.')+`<div class="notice">Частота пиков влияет на комфорт героя и вероятность выбора. Текущая роль, контроль, снос строений и стадия игры влияют на состав драфта. При банах или недостатке данных используется явно отмеченный ролевой резерв. Процент побед сам по себе не превращается в бонус победы на карте.</div><div class="cards">${ps.map(p=>{let d=poolData4(p);return `<section class="panel pool-card"><div class="section-head"><h2>${esc(p.name)}</h2><span class="tag ${d.verified?'':'dim'}">${ROLES[p.role]}</span></div><span class="sub">${p.team==null?'Свободный агент':esc(S.teams[p.team].name)}</span><p class="sub">${d.verified?'Подтверждённый срез профиля за карьеру':'Профиль не подтверждён: используется игровой ролевой резерв'}</p><div>${(d.heroes.length?d.heroes:playerPool4(p).slice(0,8)).map(h=>`<div class="pool-row"><span>${esc(h.hero)}</span><b>${h.games||'Резерв'}</b>${h.winrate!=null?'<small>'+h.winrate.toFixed(1)+'%</small>':''}</div>`).join('')}</div>${d.source?`<a class="sub" href="${esc(d.source)}" target="_blank" rel="noopener">Профиль и исходные данные ↗</a>`:''}</section>`}).join('')}</div>`}
function modelView4(){let verified=Object.values(PLAYER_HERO_DATA).filter(p=>p.verified).length;return head('HOW THE MATCH WORKS','Сначала события. Затем результат.','Движок 4 · модель управления профессиональным клубом')+`<div class="stats">${stat('Подтверждённые пулы',verified+'/80','Ролевой резерв отмечен отдельно')}${stat('Шаг модели','10 сек.','Экономика, статусы и объекты')}${stat('Условие победы','Древний','Нет финального броска вероятности')}${stat('Режимы','2','Паузы 10 минут / непрерывные часы')}</div><div class="columns"><section class="panel"><h2>Что изменилось в модели</h2><p>Каждый герой имеет отдельные net worth, банк золота, уровень, здоровье, предметные тайминги, смерть, кулдаун ультимейта и выкупа. Экономика растёт за счёт доступного фарма, убийств и объектов. Во время смерти герой теряет время для фарма.</p><p>Бой учитывает живых героев, силу предметов, комфорт героя, стадию игры, готовность способностей, вижен и преимущество защиты возвышенности. Разброс относится к исполнению конкретного боя. После боя следуют реальные для модели последствия: смерть, награды, потерянный фарм, окно для объекта.</p><p>Осадить Древнего можно через открытую линию и разрушенные T4. Случайный расчёт не может завершить карту при целой базе. При перевесе 16k сопернику потребуется цепочка успешных событий, но сумма сама по себе не делает камбэк невозможным: важны общая экономика и состояние базы.</p></section><section class="panel"><h2>Что показывает разбор реальных карт</h2><p>LGD — XG, 2 октября 2026, карта 2: XG выиграла за 32:05 с убийствами 36:7 и суммарным net worth 84k. Это пример реализации выигранных линий и сильного разгона экономики.</p><a class="sub" target="_blank" rel="noopener" href="https://www.dotabuff.com/matches/9025934049">Карточка 9025934049 ↗</a><p>Карта 3 той же серии: LGD выиграла за 47:15, хотя уступала по убийствам 26:30. В конце общий net worth был 113.1k против 108.5k. Счёт убийств не равен результату; расположение смертей по времени и реализация в постройки важнее.</p><a class="sub" target="_blank" rel="noopener" href="https://www.dotabuff.com/matches/9026055036">Карточка 9026055036 ↗</a><p>XG — Level UP, 30 сентября 2026: победа XG за 66:06, убийства 42:41, net worth XG 153.6k. Равная карта может длиться значительно дольше часа; движок не выбирает победителя принудительно на 40-й или 60-й минуте.</p><a class="sub" target="_blank" rel="noopener" href="https://www.dotabuff.com/matches/9023462170">Карточка 9023462170 ↗</a></section></div><section class="panel sources"><h2>Источники и границы точности</h2><p>Пулы собраны вручную из доступных esports-профилей Dotabuff; в срезе сохраняются до восьми наиболее играемых героев каждого подтверждённого профиля. Это карьерная статистика, которая может включать разные патчи, команды и роли. В интерфейсе у каждого игрока есть ссылка на источник. Неподтверждённые данные не выдаются за статистику игрока.</p><p>Структура модели опирается на разбор трёх реальных карт и исследование live-прогноза, учитывающее net worth, опыт и урон по строениям. Коэффициенты движка, характеристики героев, экономика, кулдауны и прочность объектов заданы для симулятора. Это не обученная на реплеях ML-модель и не точное воспроизведение актуального патча. Оценка позиции не является измеренной вероятностью победы.</p><a target="_blank" rel="noopener" href="https://eprints.whiterose.ac.uk/152931/1/Win_Prediction_in_Multi_Player_Esports_Live_Professional_Match_Prediction.pdf">Win Prediction in Multi-Player Esports: Live Professional Match Prediction ↗</a><a target="_blank" rel="noopener" href="https://www.dotabuff.com/esports/players/898754153-ame">Пример: Ame — частота Morphling, Terrorblade, Monkey King ↗</a><p>В лайв-режиме игровые часы ускорены. При скрытии вкладки, переходе в другой раздел или открытии диалога они останавливаются. При загрузке сохранения матч всегда стоит на паузе.</p></section>`}
function migrate(){migrateCareerV3();pauseLive4(false);S.matchMode=['step','live'].includes(S.matchMode)?S.matchMode:'step';S.liveSpeed=[5,10,30].includes(S.liveSpeed)?S.liveSpeed:10;if(S.active?.live&&S.active.live.engine!==4){let old=S.active.live,a=S.active,draft=old.draft||{own:old.players.map(p=>p.hero),enemy:old.enemyPlayers?.map(p=>p.hero)||HERO_ROLES4.map(p=>p[0]),bans:[],details:[[],[]]};let m=makeLive4(a,draft);m.clock=(old.minute||0)*60;let sideGold=[600*5+2055*m.clock/60+Math.max(0,old.gold||0),600*5+2055*m.clock/60+Math.max(0,-(old.gold||0))];for(let side of [0,1]){let source=side===0?old.players:old.enemyPlayers;for(let i=0;i<5;i++){let p=m.sides[side].heroes[i],stats=source?.[i];p.nw=sideGold[side]*[.28,.25,.22,.13,.12][i];p.bank=Math.min(4000,p.nw*.14);p.xp=p.nw*1.1;p.level=Math.min(30,1+Math.floor(Math.sqrt(p.xp/42)));if(stats)for(let key of ['k','d','a'])p[key]=stats[key]||0}let count=old.towers?.[1-side]||0;for(let l of m.sides[side].lanes)for(let t of l.towers){if(count<=0)break;t.hp=0;count--}}m.events=[...old.events.map(e=>({...e,sec:e.t*60})),{t:Math.floor(m.clock/60),sec:m.clock,text:'Карта перенесена на новый движок. Старые счёт и драфт сохранены; недостающие параметры восстановлены приблизительно.',type:'migration'}];m.decisions=old.decisions||[];sync4(m);m.snapshots=[];snapshot4(m);a.live=m}if(S.engineVersion!==4){S.engineVersion=4;log('Движок 4: экономика героев, последовательная осада, индивидуальные пулы и лайв-режим.')}}
if(typeof document.addEventListener==='function')document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseLive4()});

function simulateSeries(pair,final=false){let score=[0,0],need=final?3:2,mapStats=[];while(score.every(n=>n<need)){let m=makeLive4({opponent:pair[1]},autoDraft(pair),pair),guard=0;while(m.finishedSide==null&&guard++<6000)simulateTick4(m,10);if(m.finishedSide==null)throw new Error('AI map exceeded engine guard; no random winner selected.');score[m.finishedSide]++;mapStats.push({duration:m.clock,kills:[m.kills,m.deaths],gold:m.gold,winner:pair[m.finishedSide]})}return {pair:[...pair],winner:pair[score[0]>score[1]?0:1],score:score.join(':'),maps:mapStats}}
function resolvePair(pair){return simulateSeries(pair).winner}

